/* Parse one frame and pass its message to the callbacks (cb may be NULL). */
gmsg_error acme_telemetry_binary_link_process(const uint8_t* data, size_t size, const acme_telemetry_binary_link_callbacks* cb);
gmsg_error acme_telemetry_binary_link_encode_status(const acme_telemetry_status* m, uint8_t* out, size_t capacity, size_t* written);
gmsg_error acme_telemetry_binary_link_encode_status_with_header(const acme_telemetry_binary_link_header* h, const acme_telemetry_status* m, uint8_t* out, size_t capacity, size_t* written);  /* id / length fields are filled in */
gmsg_error acme_telemetry_binary_link_encode_command(const acme_telemetry_command* m, uint8_t* out, size_t capacity, size_t* written);
gmsg_error acme_telemetry_binary_link_encode_command_with_header(const acme_telemetry_binary_link_header* h, const acme_telemetry_command* m, uint8_t* out, size_t capacity, size_t* written);  /* id / length fields are filled in */
gmsg_error acme_telemetry_binary_link_encode_log(const acme_telemetry_log* m, uint8_t* out, size_t capacity, size_t* written);
gmsg_error acme_telemetry_binary_link_encode_log_with_header(const acme_telemetry_binary_link_header* h, const acme_telemetry_log* m, uint8_t* out, size_t capacity, size_t* written);  /* id / length fields are filled in */
gmsg_error acme_telemetry_binary_link_encode(const acme_telemetry_binary_link_any_message* m, uint8_t* out, size_t capacity, size_t* written);
/* Print the message held (gmp/c/print.h); kind 0 prints <none>. */
void acme_telemetry_binary_link_any_view_print(const acme_telemetry_binary_link_any_view* v, gmsg_printer* p);
void acme_telemetry_binary_link_any_message_print(const acme_telemetry_binary_link_any_message* m, gmsg_printer* p);

/* GMSG_ERR_BUFFER_FULL when size < ACME_TELEMETRY_BINARY_LINK_MAX_FRAME. Clears the callbacks. */
gmsg_error acme_telemetry_binary_link_stream_init(acme_telemetry_binary_link_stream* s, uint8_t* buf, size_t size);
/* Push data and deliver every complete frame; returns the number of frames delivered. */
static inline size_t acme_telemetry_binary_link_stream_feed(acme_telemetry_binary_link_stream* s, const uint8_t* data, size_t n) { return gmsg_stream_feed(&s->base, data, n); }
static inline size_t acme_telemetry_binary_link_stream_push(acme_telemetry_binary_link_stream* s, const uint8_t* data, size_t n) { return gmsg_stream_push(&s->base, data, n); }
static inline bool acme_telemetry_binary_link_stream_next(acme_telemetry_binary_link_stream* s) { return gmsg_stream_next(&s->base); }
static inline void acme_telemetry_binary_link_stream_reset(acme_telemetry_binary_link_stream* s) { gmsg_stream_reset(&s->base); }
static inline const gmsg_stream_stats* acme_telemetry_binary_link_stream_stats(const acme_telemetry_binary_link_stream* s) { return &s->base.stats; }
static inline gmsg_error acme_telemetry_binary_link_stream_last_error(const acme_telemetry_binary_link_stream* s) { return s->base.last_error; }
static inline size_t acme_telemetry_binary_link_stream_buffered(const acme_telemetry_binary_link_stream* s) { return gmsg_stream_buffered(&s->base); }
/* Changes whenever views returned by the poll functions expire. */
static inline uint32_t acme_telemetry_binary_link_stream_generation(const acme_telemetry_binary_link_stream* s) { return gmsg_stream_generation(&s->base); }

/* Pull API. Returned views point into the stream buffer and stay valid until the next call on the
 * stream. Message callbacks are never called (except by poll_for for other messages); errors go to
 * cb.on_error, except in poll_event, which returns them. All return false / GMSG_POLL_NEED_MORE when
 * more input is needed. */
bool acme_telemetry_binary_link_stream_poll(acme_telemetry_binary_link_stream* s, acme_telemetry_binary_link_any_view* out);
bool acme_telemetry_binary_link_stream_poll_frame(acme_telemetry_binary_link_stream* s, acme_telemetry_binary_link_received* out);
bool acme_telemetry_binary_link_stream_poll_message(acme_telemetry_binary_link_stream* s, acme_telemetry_binary_link_any_message* out);  /* decoded copy; decode failures are reported like bad frames */
gmsg_poll acme_telemetry_binary_link_stream_poll_event(acme_telemetry_binary_link_stream* s, acme_telemetry_binary_link_event* out);
/* Wait for a message of `kind`; other messages go to the callbacks (message slot, then on_frame). */
bool acme_telemetry_binary_link_stream_poll_for(acme_telemetry_binary_link_stream* s, acme_telemetry_binary_link_kind kind, acme_telemetry_binary_link_any_view* out);

